<?php namespace App\Http\Controllers;use Illuminate\Http\Request;use Illuminate\Support\Str;class DashboardController extends Controller{private function s($r){return $r->user()->store()->firstOrFail();}public function index(Request $r){$s=$this->s($r);$stats=['products'=>$s->products()->count(),'links'=>$s->links()->count(),'orders'=>$s->orders()->count(),'revenue'=>$s->orders()->where('status','paid')->sum('amount')];return view('dashboard.index',compact('s','stats'));}public function editStore(Request $r){$s=$this->s($r);return view('dashboard.store',compact('s'));}public function updateStore(Request $r){$s=$this->s($r);$s->update($r->validate(['display_name'=>'required|max:100','username'=>'required|alpha_dash|max:40|unique:stores,username,'.$s->id,'bio'=>'nullable|max:500','avatar_url'=>'nullable|url']));return back();}public function addLink(Request $r){$s=$this->s($r);$s->links()->create($r->validate(['title'=>'required|max:100','url'=>'required|url'])+['position'=>0,'active'=>true]);return back();}public function deleteLink(Request $r,$link){$this->s($r)->links()->findOrFail($link)->delete();return back();}public function deleteProduct(Request $r,$product){$this->s($r)->products()->findOrFail($product)->delete();return back();}public function products(Request $r){$s=$this->s($r);$products=$s->products()->get();return view('dashboard.products',compact('s','products'));}public function createProduct(Request $r){$s=$this->s($r);$d=$r->validate(['name'=>'required|max:160','description'=>'nullable','type'=>'required|in:physical,digital,service','price'=>'required|numeric|min:0','currency'=>'required|size:3','image_url'=>'nullable|url','inventory'=>'nullable|integer|min:0']);$d['slug']=Str::slug($d['name']).'-'.Str::lower(Str::random(5));$d['active']=true;$s->products()->create($d);return back();}public function orders(Request $r){$s=$this->s($r);$orders=$s->orders()->latest()->get();return view('dashboard.orders',compact('s','orders'));}}